import {STORAGE_KEY,blankState,eligible,shuffle,generate,replacements,parseWeight,newWorkout,replaceEntry,stats,previousWeight,validateBackup} from './core.mjs';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),toastEl=document.querySelector('#toast');
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',history:'<path d="M4 20V10m8 10V4m8 16v-7"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v2"/>',arrow:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m15 5-7 7 7 7"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',circle:'<circle cx="12" cy="12" r="9"/>',dumbbell:'<path d="m7 7 10 10M3 8l5-5m8 18 5-5M5 10l5-5m4 14 5-5"/>',shuffle:'<path d="M3 5h3l12 14h3m-4-4 4 4-4 2M3 19h3l4-5m4-4 4-5h3m-4-2 4 2-4 4"/>',plus:'<path d="M12 4v16M4 12h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',play:'<path d="m8 4 12 8-12 8z"/>',undo:'<path d="m7 4-4 5 4 4M3 9h10a6 6 0 0 1 0 12"/>',replace:'<path d="M3 7h16m-4-4 4 4-4 4M21 17H5m4-4-4 4 4 4"/>'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.dumbbell}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const modes={favorites:['Только избранные','Тренировка из любимых упражнений','heart'],random:['Случайная тренировка','Каждый раз — новый набор','shuffle'],custom:['Моя тренировка','Выбирай упражнения самостоятельно','plus']};
const fmt=n=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:2});
const date=s=>new Date(s).toLocaleDateString('ru-RU',{day:'numeric',month:'long'});
let catalog=[],byID=new Map(),state=blankState(),page='home',mode='favorites',plan=[],selection=[],query='',filter='favorite',body=[],equipment=[],count=6,queue=[],lastChoice=null,summaryID=null,listLimit=60,toastTimer,modalContext=null,storageBlocked=false,removedChoice=null;
const favorites=()=>Object.values(state.choices).filter(x=>x==='favorite').length;
function toast(text){clearTimeout(toastTimer);toastEl.textContent=text;toastEl.classList.add('show');toastTimer=setTimeout(()=>toastEl.classList.remove('show'),2600);}
function storageError(message){const el=document.querySelector('#storage-error');el.hidden=false;el.replaceChildren(document.createTextNode(message));const b=document.createElement('button');b.className='text-btn';b.textContent='Выгрузить данные';b.onclick=exportData;el.append(b);}
function persist(){
  if(storageBlocked){storageError('Сохранение приостановлено: сначала восстанови или выгрузи существующие данные.');return false;}
  try{state.revision++;localStorage.setItem(STORAGE_KEY,JSON.stringify(state));document.querySelector('#storage-error').hidden=true;return true;}
  catch{storageError('Браузер не сохранил изменения. Проверь свободное место или выгрузи резервную копию.');return false;}
}
function transact(fn){const old=structuredClone(state);fn();if(!persist()){state=old;return false;}return true;}
function go(next){page=next;query='';listLimit=60;render();window.scrollTo({top:0,behavior:'instant'});}
function brand(){return '<div class="brand"><span class="logo-mark">P</span>Pumpy</div>';}
function nav(){const items=[['home','Сегодня','home'],['library','Упражнения','star'],['history','История','history'],['profile','Профиль','user']];return items.map(([p,t,i])=>`<button data-action="nav" data-page="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('');}
function art(){return '<div class="art" aria-hidden="true"><div class="barbell"></div></div>';}
function media(e){return `<figure class="exercise-media"><div class="media-stage"><img src="${esc(e.animation)}" width="180" height="180" alt="Анимация: ${esc(e.name)}" referrerpolicy="no-referrer"><span class="media-loading">Загружаем анимацию…</span><div class="media-failure" hidden><p>Анимация не загрузилась</p><button class="text-btn" data-action="retry-media">Повторить</button><a href="${esc(e.animation)}" target="_blank" rel="noopener noreferrer">Открыть отдельно ↗</a></div></div><figcaption><a href="https://gymvisual.com/" target="_blank" rel="noopener noreferrer">© Gym visual</a><span>Техника в движении</span></figcaption></figure>`;}
function head(title,subtitle='',action=''){return `<div class="page-head"><div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`;}
function empty(title,text,action=''){return `<div class="empty">${icon('dumbbell')}<h3>${title}</h3><p>${text}</p>${action}</div>`;}
function button(text,action,cls='primary',attrs=''){return `<button class="btn ${cls}" data-action="${action}" ${attrs}>${text}</button>`;}
function render(){
  if(!state.onboarded&&page!=='swipe'){renderWelcome();return;}
  const content={home:homeView,swipe:swipeView,generator:generatorView,library:libraryView,workout:workoutView,history:historyView,summary:summaryView,profile:profileView}[page]||homeView;
  app.innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<nav class="nav" aria-label="Основная навигация">${nav()}</nav><div class="small-note">Твой ритм. Твои упражнения.<br>Твои маленькие победы.</div></aside><main class="main"><header class="topbar">${brand()}<span class="day">${new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})}</span><button class="avatar" data-action="nav" data-page="profile" aria-label="Профиль">${icon('user')}</button></header>${content()}</main><nav class="mobile-nav" aria-label="Основная навигация">${nav()}</nav></div>`;
  if(page==='swipe')bindSwipe();
  if(page==='library')bindListSwipes();
}
function renderWelcome(){app.innerHTML=`<main class="welcome">${brand()}<div class="welcome-grid"><section><span class="eyebrow">Тренировки под тебя</span><h1>Делай то,<br>что <span class="accent">нравится.</span></h1><p class="intro">Выбери любимые упражнения один раз — и собирай тренировки, к которым хочется возвращаться.</p>${button('Начать подбор '+icon('arrow'),'swipe-start')}<button class="text-btn skip" data-action="onboard-skip">Пропустить, выбрать позже</button></section><div class="welcome-visual"><span class="eyebrow">Меньше случайного. Больше твоего.</span>${art()}<h2>Свайп вправо — любовь.<br>Влево — идём дальше.</h2><p>Никаких обязательных анкет.<br>Закончить выбор можно в любой момент.</p></div></div><footer class="welcome-footer"><span>1324 упражнения · твой темп</span><span>Без таймеров и спешки</span></footer></main>`;}
function homeView(){const last=state.history[0];const total=state.history.reduce((n,w)=>n+stats(w).done,0);return `${head('Что тренируем<br>сегодня?','Хорошая тренировка начинается с твоего выбора.')} ${state.active?`<div class="resume row"><div><h3>Продолжим с того же места?</h3><p>${esc(modes[state.active.mode][0])} · ${stats(state.active).done} подходов выполнено</p></div>${button('Продолжить '+icon('play'),'resume')}</div>`:''}<div class="home-grid"><div class="mode-list">${Object.entries(modes).map(([m,[title,sub,i]])=>`<button class="mode" data-action="mode" data-mode="${m}"><span class="mode-icon">${icon(i)}</span><span><h3>${title}</h3><p>${sub}</p></span>${icon('arrow','arrow')}</button>`).join('')}</div><aside class="little-card"><span class="eyebrow">Твой личный набор</span>${art()}<h2>Больше любимых движений</h2><p>Пара свайпов — и Pumpy лучше понимает твой выбор.</p><button class="text-btn" data-action="swipe-start">Настроить предпочтения →</button></aside></div><div class="stats"><div class="stat"><strong>${favorites()}</strong><span>в избранном</span></div><div class="stat"><strong>${state.history.length}</strong><span>тренировок</span></div><div class="stat"><strong>${total}</strong><span>подходов сделано</span></div></div><h2 class="section-title">Последняя тренировка</h2>${last?`<div class="white-card row"><div><h3>${esc(modes[last.mode][0])}</h3><p class="muted">${date(last.date)} · ${last.exercises.length} упражнений</p><button class="text-btn" data-action="summary" data-id="${esc(last.id)}">Посмотреть результат →</button></div><button class="btn secondary" data-action="repeat" data-id="${esc(last.id)}">Повторить</button></div>`:empty('Пока чистый лист','Твоя первая тренировка появится здесь. Начни с любимых упражнений.')}`;}
function startSwipe(){queue=shuffle(catalog.filter(e=>!state.choices[e.id]||state.choices[e.id]==='neutral')).map(e=>e.id);lastChoice=null;go('swipe');}
function swipeView(){const e=byID.get(queue[0]);return `<div class="swipe-layout">${head('Что тебе нравится?','Вправо — в избранное. Влево — исключить.','<button class="text-btn" data-action="onboard-skip">Пропустить</button>')}<div class="swipe-status"><span class="accent" id="favorite-count">${favorites()} в избранном</span><span class="muted">Выбор за тобой</span></div>${e?`<article class="swipe-card" id="swipe-card" aria-label="Карточка упражнения: ${esc(e.name)}"><div class="swipe-stamp" id="swipe-stamp"></div>${media(e)}<h2>${esc(e.name)}</h2><p class="meta">${esc(e.subtitle||e.bodyPart+' · '+e.equipment)}</p><button class="text-btn" data-action="detail" data-id="${e.id}">Как выполнять →</button></article><div class="swipe-actions"><button class="circle no" data-action="dislike" aria-label="Исключить упражнение">${icon('x')}</button><button class="text-btn" data-action="swipe-next">Дальше</button><button class="circle yes" data-action="favorite" aria-label="Добавить в избранное">${icon('heart')}</button></div><div class="center">${lastChoice?'<button class="text-btn" data-action="undo">Отменить последний выбор</button>':'<p class="muted" style="font-size:12px">Можно закончить в любой момент</p>'}</div>`:empty('Всё просмотрено','Твои предпочтения сохранены. Изменить их можно в каталоге.',button('На главную','onboard-skip'))}</div>`;}
function choose(value){const id=queue[0];if(!id)return;const old=state.choices[id]||'neutral';if(transact(()=>state.choices[id]=value)){queue.shift();lastChoice={id,old};render();toast(value==='favorite'?'В избранном ♥':'Больше не попадёт в подборки');}}
function bindSwipe(){const card=document.querySelector('#swipe-card');if(!card)return;let start=null,dx=0;card.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;start={x:e.clientX,y:e.clientY};dx=0;card.setPointerCapture(e.pointerId);});card.addEventListener('pointermove',e=>{if(!start)return;dx=e.clientX-start.x;const dy=e.clientY-start.y;if(Math.abs(dy)>Math.abs(dx)&&Math.abs(dx)<30)return;card.style.transform=`translateX(${dx*.7}px) rotate(${dx/25}deg)`;const stamp=document.querySelector('#swipe-stamp');stamp.textContent=dx>0?'В ИЗБРАННОЕ':'ИСКЛЮЧИТЬ';stamp.style.color=dx>0?'var(--green)':'var(--red)';stamp.style.opacity=Math.min(Math.abs(dx)/100,1);});const end=e=>{if(!start)return;const dy=e.clientY-start.y;start=null;if(Math.abs(dx)>85&&Math.abs(dx)>Math.abs(dy))choose(dx>0?'favorite':'disliked');else{card.style.transform='';document.querySelector('#swipe-stamp').style.opacity=0;}};card.addEventListener('pointerup',end);card.addEventListener('pointercancel',()=>{start=null;card.style.transform='';document.querySelector('#swipe-stamp').style.opacity=0;});}
function filterFields(){return `<div class="filters">${mode!=='custom'?`<div class="field count"><label for="count">Упражнений в тренировке</label><select id="count">${Array.from({length:12},(_,i)=>`<option value="${i+1}" ${count===i+1?'selected':''}>${i+1}</option>`).join('')}</select></div>`:''}${[['body','Мышцы',body,'Всё тело'],['equipment','Инвентарь',equipment,'Любой']].map(([kind,label,values,all])=>`<div class="field"><span class="filter-label">${label}</span><button class="filter-picker" data-action="filter-open" data-kind="${kind}" aria-haspopup="dialog" aria-label="${label}: ${esc(values.length?values.join(', '):all)}"><span>${esc(values.length?values.join(', '):all)}</span>${icon('arrow')}</button></div>`).join('')}</div><p class="filter-help">Можно выбрать несколько групп мышц и несколько видов инвентаря.</p>`;}
function openFilters(kind){const values=[...(kind==='body'?body:equipment)];modalContext={type:'filters',kind,values};const options=[...new Set(catalog.map(e=>kind==='body'?e.bodyPart:e.equipment))].sort();const all=kind==='body'?'Всё тело':'Любой инвентарь';showModal(kind==='body'?'Какие мышцы тренируем?':'Какой инвентарь доступен?',`<p class="muted">Отметь один или несколько вариантов.</p><fieldset class="multi-options"><legend class="sr-only">${kind==='body'?'Группы мышц':'Виды инвентаря'}</legend><label class="multi-option all-option"><span>${all}</span><input type="checkbox" data-filter-all ${values.length?'':'checked'}></label>${options.map(value=>`<label class="multi-option"><span>${esc(value)}</span><input type="checkbox" data-filter-option value="${esc(value)}" ${values.includes(value)?'checked':''}></label>`).join('')}</fieldset><div class="filter-footer"><span id="filter-selection-count" class="muted">${values.length?'Выбрано: '+values.length:all}</span>${button('Применить','filter-apply','primary')}${button('Отмена','modal-close','secondary')}</div>`);}

function generatorView(){const pool=eligible(catalog,state.choices,mode,body,equipment);return `<button class="back" data-action="nav" data-page="home">${icon('back')} На главную</button>${head(esc(modes[mode][0]),mode==='favorites'?'Только любимые. Никаких компромиссов.':mode==='custom'?'Собери свой набор — до 12 упражнений.':'Выбери мышцы и инвентарь. Остальное соберём.')} ${filterFields()}<p class="count-line">Доступно упражнений: ${pool.length}</p>${mode==='custom'?`<input class="search" id="search" type="search" placeholder="Найти упражнение" aria-label="Найти упражнение" value="${esc(query)}"><div class="exercise-list" id="results">${exerciseResults(pool,true)}</div><div class="sticky-action">${button(`Начать · ${selection.length} упражнений`,'start','primary wide',selection.length?'':'disabled')}</div>`:pool.length?`${button('Собрать тренировку '+icon('shuffle'),'generate','primary')}${plan.length?`<h2 class="section-title">Твой план на сегодня</h2>${planList(plan)}${plan.length<count?'<p class="count-line">Подходящих упражнений меньше — добавили все, без повторов.</p>':''}<div class="sticky-action">${button('Начать тренировку '+icon('play'),'start','primary wide')}</div>`:''}`:empty('Пока нет подходящих упражнений',mode==='favorites'?'Добавь любимые упражнения или измени фильтры. Случайных упражнений здесь не будет.':'Попробуй выбрать другой инвентарь или мышцы.',button('Выбрать упражнения','swipe-start','secondary'))}`;}
function planList(ids){return `<div class="plan-list">${ids.map((id,i)=>{const e=byID.get(id);return `<div class="plan-item"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.name)}</h3><p>${esc(e.bodyPart)} · ${esc(e.equipment)} · 3 подхода</p></div></div>`;}).join('')}</div>`;}
function matches(e){return !query||`${e.name} ${e.bodyPart} ${e.equipment}`.toLocaleLowerCase('ru').includes(query.toLocaleLowerCase('ru'));}
function exerciseResults(pool,custom=false){const results=pool.filter(matches);return results.slice(0,listLimit).map(e=>{
  const label=`<span class="item-icon">${icon('dumbbell')}</span><span class="item-text"><h3>${esc(e.name)}</h3><p>${esc(e.bodyPart)} · ${esc(e.equipment)}</p>${custom?'<span class="preview-label">Посмотреть анимацию →</span>':''}</span>`;
  if(custom)return `<div class="exercise-item custom-item ${selection.includes(e.id)?'chosen':''}"><button class="item-preview" data-action="preview" data-id="${e.id}" aria-label="Предпросмотр: ${esc(e.name)}">${label}</button><button class="quick-add" data-action="select" data-id="${e.id}" aria-label="${selection.includes(e.id)?'Убрать из тренировки':'Добавить в тренировку'}: ${esc(e.name)}" aria-pressed="${selection.includes(e.id)}">${icon(selection.includes(e.id)?'check':'plus')}</button></div>`;
  const item=`<button class="exercise-item" data-action="detail" data-id="${e.id}">${label}${icon(state.choices[e.id]==='favorite'?'heart':'arrow','check')}</button>`;
  if(filter==='all')return item;
  return `<div class="swipe-row" data-id="${e.id}"><button class="row-remove" data-action="remove-pref" data-id="${e.id}" aria-label="Убрать ${esc(e.name)} из ${filter==='favorite'?'избранного':'исключённых'}">${icon('x')}<span>Убрать</span></button><div class="row-front">${item}<button class="remove-handle" data-action="remove-pref" data-id="${e.id}" aria-label="Убрать из списка: ${esc(e.name)}">${icon('x')}</button></div></div>`;
  }).join('')+(results.length>listLimit?button(`Ещё ${Math.min(60,results.length-listLimit)} упражнений`,'more','secondary wide'):'')+(results.length?'':empty('Ничего не нашлось','Попробуй другое название или измени фильтр.'));}
function bindListSwipes(){document.querySelectorAll('.swipe-row').forEach(row=>{if(row.dataset.bound)return;row.dataset.bound='1';const front=row.querySelector('.row-front');let start=null,moved=false;front.addEventListener('pointerdown',e=>{start={x:e.clientX,y:e.clientY};moved=false;});front.addEventListener('pointermove',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)>18&&Math.abs(dx)>Math.abs(dy)){moved=true;front.setPointerCapture(e.pointerId);front.style.transform=`translateX(${Math.max(-96,Math.min(0,dx))}px)`;}});front.addEventListener('pointerup',e=>{if(!start)return;const open=moved&&e.clientX-start.x<-40;start=null;front.style.transform=open?'translateX(-96px)':'';row.classList.toggle('revealed',open);});front.addEventListener('pointercancel',()=>{start=null;front.style.transform='';});front.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopPropagation();moved=false;}},true);row.querySelector('.row-remove').addEventListener('focus',()=>{front.style.transform='translateX(-96px)';});});}
function libraryPool(){return catalog.filter(e=>filter==='all'||state.choices[e.id]===filter);}
function libraryView(){return `${head('Твои упражнения',`${favorites()} в избранном · ${catalog.length} в каталоге`,'<button class="text-btn" data-action="swipe-start">Свайпы →</button>')}<div class="segments" aria-label="Фильтр упражнений">${[['favorite','Избранные'],['all','Все'],['disliked','Исключённые']].map(([v,t])=>`<button data-action="filter" data-filter="${v}" class="${filter===v?'selected':''}" aria-pressed="${filter===v}">${t}</button>`).join('')}</div>${filter!=='all'?'<p class="count-line">Свайп влево → «Убрать» из списка</p>':''}${removedChoice?'<button class="text-btn" data-action="undo-remove">Отменить удаление из списка</button>':''}<input class="search" id="search" type="search" value="${esc(query)}" placeholder="Название, мышцы или инвентарь" aria-label="Поиск упражнений"><div class="exercise-list" id="results">${libraryPool().length?exerciseResults(libraryPool()):empty('Здесь пока пусто','Пара свайпов — и здесь появится твой личный набор.',button('Начать выбор','swipe-start','secondary'))}</div>`;}
function workoutView(){const w=state.active;if(!w)return empty('Нет активной тренировки','Выбери режим на главной.',button('На главную','home'));const entry=w.exercises[w.index],e=byID.get(entry.exerciseID);return `<div class="workout-container"><div class="row"><button class="back" data-action="nav" data-page="home">${icon('back')} Свернуть</button><button class="text-btn" data-action="finish">Завершить</button></div>${head('Тренировка',`${esc(modes[w.mode][0])} · ${w.index+1} из ${w.exercises.length}`)}<div class="progress" aria-label="Прогресс по упражнениям"><span style="width:${(w.index+1)/w.exercises.length*100}%"></span></div><div class="workout-hero"><span class="eyebrow">${esc(e.bodyPart)}</span><h2>${esc(e.name)}</h2><p>${esc(e.equipment)} · 3 подхода</p><div class="row"><button class="text-btn" data-action="replace">Заменить упражнение</button><button class="text-btn" data-action="detail" data-id="${e.id}">Техника →</button></div></div>${media(e)}<div class="sets-head"><span>№</span><span>Повторы</span><span>Вес, кг</span><span>Готово</span></div>${entry.sets.map((s,i)=>{const prev=previousWeight(state.history,e.id,i);return `<div class="set-group"><div class="set-line ${s.done?'done':''}"><span>${i+1}</span><input type="text" inputmode="numeric" pattern="[0-9]*" data-set="${i}" data-field="reps" value="${s.reps}" aria-label="Повторы, подход ${i+1}" autocomplete="off"><input type="text" inputmode="decimal" data-set="${i}" data-field="weight" placeholder="Вес, кг" value="${s.weight===null?'':esc(String(s.weight).replace('.',','))}" aria-label="Вес, подход ${i+1}" autocomplete="off"><button class="set-check ${s.done?'completed':''}" data-action="set-done" data-set="${i}" aria-label="Подход ${i+1} выполнен" aria-pressed="${s.done}">${icon(s.done?'check':'circle')}</button></div><p class="input-error" role="status"></p>${prev!==null?`<p class="previous">В прошлый раз: ${fmt(prev)} кг</p>`:''}</div>`;}).join('')}<div class="hint">Вес сохраняется после ввода. Отметь кружком выполненный подход — и двигайся в своём темпе.</div><div class="row">${w.index>0?button('Назад','workout-prev','secondary'):''}${button(w.index<w.exercises.length-1?'Следующее упражнение →':'Завершить тренировку','workout-next','primary wide')}</div></div>`;}
function historyView(){return `${head('Каждая тренировка<br>имеет значение.',`${state.history.length} тренировок в твоей истории`)}<div class="stack">${state.history.length?state.history.map(w=>`<button class="history-card" data-action="summary" data-id="${esc(w.id)}"><div class="row"><h3>${esc(modes[w.mode][0])}</h3>${icon('arrow')}</div><p>${date(w.date)} · ${w.exercises.length} упражнений · ${stats(w).done} подходов</p></button>`).join(''):empty('Твой прогресс — впереди','Заверши первую тренировку. Здесь останутся все упражнения, подходы и веса.',button('К тренировкам','home','secondary'))}</div>`;}
function summaryView(){const w=state.history.find(w=>w.id===summaryID);if(!w)return empty('Тренировка не найдена','Вернись к истории.');const s=stats(w);return `<button class="back" data-action="nav" data-page="history">${icon('back')} История</button><div class="summary-hero">${icon('check')}<h1>Ты это сделал.</h1><p class="muted" style="margin-top:12px">${date(w.date)} · ${esc(modes[w.mode][0])}</p></div><div class="stats"><div class="stat"><strong>${w.exercises.length}</strong><span>упражнений</span></div><div class="stat"><strong>${s.done}/${s.total}</strong><span>подходов</span></div><div class="stat"><strong>${fmt(s.volume)}</strong><span>кг объём</span></div></div><div class="stack" style="margin-top:24px">${w.exercises.map(entry=>`<section class="white-card"><h3 style="margin-bottom:15px">${esc(byID.get(entry.exerciseID).name)}</h3>${entry.sets.map((set,i)=>`<div class="summary-set"><span>${i+1}. ${set.reps} повторов</span><span>${set.weight===null?'Без веса':fmt(set.weight)+' кг'}</span><span aria-label="${set.done?'Выполнен':'Не выполнен'}">${icon(set.done?'check':'circle')}</span></div>`).join('')}</section>`).join('')}</div><div class="sticky-action">${button('Повторить тренировку','repeat','primary wide',`data-id="${esc(w.id)}"`)}</div>`;}
function profileView(){return `${head('Твой Pumpy','Всё нужное для тренировок — под рукой.')}<div class="profile-grid"><section class="card"><h3>Твои предпочтения</h3><p>${favorites()} избранных · ${Object.values(state.choices).filter(x=>x==='disliked').length} исключённых упражнений</p>${button('Выбрать свайпами','swipe-start','secondary')}</section><section class="card install"><h3>Как приложение на iPhone</h3><ol><li>Открой эту страницу в Safari.</li><li>Нажми «Поделиться».</li><li>Выбери «На экран Домой».</li></ol><p>Для открытия нужен интернет. Mac и App Store не нужны.</p></section><section class="white-card"><h3>Данные под твоим контролем</h3><p>Предпочтения и тренировки сохраняются в этом браузере. На другом устройстве они не появятся автоматически. Очистка данных браузера может удалить историю.</p>${button(icon('download')+' Скачать копию','export','secondary')}${button('Восстановить из копии','import','secondary')}<p style="font-size:12px;margin-top:14px">Сохрани копию перед сменой устройства или браузера. На экране Домой данные могут храниться отдельно от Safari.</p></section><section class="white-card"><h3>Сделано для твоего темпа</h3><p>1324 упражнения, русские инструкции, никаких таймеров. Названия сохранены из исходного каталога.</p><p style="margin:16px 0">Изменение предпочтений влияет на новые подборки и замены. Уже начатая тренировка сохраняет свой состав.</p><a href="./Dataset-LICENSE.txt" target="_blank" rel="noopener">Лицензия каталога · MIT</a></section></div>`;}
function showModal(title,content){modal.innerHTML=`<div class="dialog-head"><h2 id="modal-title">${title}</h2><button class="close" data-action="modal-close" aria-label="Закрыть">${icon('x')}</button></div>${content}`;if(!modal.open)modal.showModal();document.body.classList.add('no-scroll');}
function closeModal(){modal.close();document.body.classList.remove('no-scroll');modalContext=null;}
modal.addEventListener('close',()=>document.body.classList.remove('no-scroll'));
function detail(id,custom=false){const e=byID.get(id);if(!e)return;modalContext={type:'detail',id,custom};showModal(esc(e.name),`<p class="muted" style="margin-bottom:16px">${esc(e.bodyPart)} · ${esc(e.equipment)}</p>${media(e)}${custom?`<div class="preview-action">${button(selection.includes(id)?'Убрать из тренировки':'Добавить в тренировку','select','primary wide',`data-id="${id}"`)}</div>`:''}<div class="pref-buttons">${[['favorite','♥ Избранное'],['neutral','Без оценки'],['disliked','Исключить']].map(([v,t])=>`<button data-action="pref" data-id="${e.id}" data-pref="${v}" class="${(state.choices[id]||'neutral')===v?'selected':''}">${t}</button>`).join('')}</div><h3 style="margin:20px 0 10px">Как выполнять</h3><p class="dialog-copy">${esc(e.instructions)}</p>`);}
function replaceModal(){const w=state.active,entry=w.exercises[w.index],pool=replacements(catalog,state.choices,w,entry);modalContext={type:'replace',pool};showModal('Замена упражнения',`<p class="muted" style="font-size:13px">Сначала — похожие мышцы и инвентарь. ${w.mode==='favorites'?'Только из избранных.':''}</p><input class="search" id="replacement-search" type="search" placeholder="Найти замену" aria-label="Найти замену"><div class="dialog-results exercise-list" id="replacement-results">${replacementResults(pool,'')}</div>`);}
function replacementResults(pool,q){const filtered=pool.filter(e=>e.name.toLowerCase().includes(q.toLowerCase()));return filtered.length?filtered.slice(0,80).map(e=>`<button class="exercise-item" data-action="replace-select" data-id="${e.id}"><span class="item-text"><h3>${esc(e.name)}</h3><p>${esc(e.bodyPart)} · ${esc(e.equipment)}</p></span>${icon('arrow')}</button>`).join(''):empty('Нет подходящей замены','Все подходящие упражнения уже в тренировке. Можно добавить больше избранных.');}
function fieldsValid(){const invalid=document.querySelector('[data-field].invalid');if(invalid){invalid.focus();toast('Проверь введённое значение');return false;}return true;}
function finishPrompt(){if(!fieldsValid())return;const s=stats(state.active);showModal('Завершить тренировку?',`<p class="dialog-copy">Выполнено ${s.done} из ${s.total} подходов. Сохраним все введённые веса и отметки.</p><div class="dialog-actions">${button('Сохранить и завершить','finish-confirm')}${button('Продолжить','modal-close','secondary')}</div>`);}
function start(ids){if(state.active){showModal('У тебя есть активная тренировка',`<p class="dialog-copy">Продолжи её или заверши, прежде чем начинать новую. Все подходы сохранены.</p><div class="dialog-actions">${button('Продолжить тренировку','resume')}${button('Закрыть','modal-close','secondary')}</div>`);return;}try{const w=newWorkout(ids,mode,state.choices,catalog);if(transact(()=>state.active=w)){closeModal();go('workout');}}catch(e){toast(e.message);}}
function exportData(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`pumpy-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Резервная копия подготовлена');}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled)return;const a=target.dataset.action,id=target.dataset.id;
  if(page==='workout'&&['nav','home','workout-next','workout-prev','replace','set-done'].includes(a)&&!fieldsValid())return;
  switch(a){
    case 'nav':if(!state.onboarded){if(!transact(()=>state.onboarded=true))return;}go(target.dataset.page);break;
    case 'home':go('home');break;
    case 'swipe-start':startSwipe();break;
    case 'onboard-skip':if(transact(()=>state.onboarded=true))go('home');break;
    case 'favorite':choose('favorite');break;
    case 'dislike':choose('disliked');break;
    case 'swipe-next':queue.push(queue.shift());render();break;
    case 'undo':if(lastChoice&&transact(()=>state.choices[lastChoice.id]=lastChoice.old)){queue.unshift(lastChoice.id);lastChoice=null;render();}break;
    case 'mode':mode=target.dataset.mode;plan=[];selection=[];body=[];equipment=[];count=6;go('generator');break;
    case 'filter-open':openFilters(target.dataset.kind);break;
    case 'filter-apply':if(modalContext?.type==='filters'){if(modalContext.kind==='body')body=[...modalContext.values];else equipment=[...modalContext.values];plan=[];closeModal();render();}break;
    case 'generate':plan=generate(catalog,state.choices,mode,count,body,equipment).map(e=>e.id);render();break;
    case 'start':start(mode==='custom'?selection:plan);break;
    case 'select':if(selection.includes(id))selection=selection.filter(x=>x!==id);else if(selection.length<12)selection.push(id);else{toast('Максимум 12 упражнений');return;}document.querySelector('#results').innerHTML=exerciseResults(eligible(catalog,state.choices,mode,body,equipment),true);const startBtn=document.querySelector('[data-action="start"]');startBtn.textContent=`Начать · ${selection.length} упражнений`;startBtn.disabled=!selection.length;if(modal.open&&modalContext?.custom){closeModal();toast(selection.includes(id)?'Добавлено в тренировку':'Убрано из тренировки');}break;
    case 'filter':filter=target.dataset.filter;query='';listLimit=60;render();break;
    case 'more':listLimit+=60;document.querySelector('#results').innerHTML=exerciseResults(page==='library'?libraryPool():eligible(catalog,state.choices,mode,body,equipment),page==='generator');if(page==='library')bindListSwipes();break;
    case 'detail':detail(id);break;
    case 'preview':detail(id,true);break;
    case 'retry-media':{const stage=target.closest('.media-stage');stage.querySelector('.media-failure').hidden=true;stage.querySelector('.media-loading').hidden=false;const img=stage.querySelector('img');img.hidden=false;img.src=img.src;break;}
    case 'remove-pref':{const old=state.choices[id];if(transact(()=>state.choices[id]='neutral')){removedChoice={id,old};render();toast('Убрано из списка. Упражнение снова без оценки.');}break;}
    case 'undo-remove':if(removedChoice&&transact(()=>state.choices[removedChoice.id]=removedChoice.old)){removedChoice=null;render();toast('Упражнение возвращено');}break;
    case 'pref':{const custom=modalContext?.custom;if(transact(()=>state.choices[id]=target.dataset.pref)){if(page==='swipe'&&queue[0]===id&&target.dataset.pref!=='neutral'){queue.shift();lastChoice=null;}if(target.dataset.pref==='disliked'){selection=selection.filter(x=>x!==id);plan=plan.filter(x=>x!==id);}render();detail(id,custom);}break;}
    case 'resume':closeModal();go('workout');break;
    case 'set-done':if(transact(()=>{const s=state.active.exercises[state.active.index].sets[Number(target.dataset.set)];s.done=!s.done;}))render();break;
    case 'workout-prev':if(transact(()=>state.active.index=Math.max(0,state.active.index-1)))render();break;
    case 'workout-next':if(state.active.index===state.active.exercises.length-1)finishPrompt();else if(transact(()=>state.active.index++)){render();window.scrollTo(0,0);}break;
    case 'finish':finishPrompt();break;
    case 'finish-confirm':summaryID=state.active.id;if(transact(()=>{state.active.finishedAt=new Date().toISOString();state.history.unshift(state.active);state.active=null;})){closeModal();go('summary');}break;
    case 'replace':replaceModal();break;
    case 'replace-select':showModal('Заменить упражнение?',`<p class="dialog-copy">${esc(byID.get(id).name)}<br><br>Веса и отметки заменяемого упражнения будут очищены. Остальные упражнения останутся прежними.</p><div class="dialog-actions">${button('Заменить','replace-confirm','primary',`data-id="${id}"`)}${button('Отмена','modal-close','secondary')}</div>`);break;
    case 'replace-confirm':try{const replacement=replaceEntry(state.active,state.active.index,id,catalog,state.choices);if(transact(()=>state.active=replacement)){closeModal();render();toast('Упражнение заменено');}}catch(e){toast(e.message);}break;
    case 'summary':summaryID=id;go('summary');break;
    case 'repeat':{const w=state.history.find(w=>w.id===id);mode=w.mode;start(w.exercises.map(e=>e.exerciseID));break;}
    case 'modal-close':closeModal();break;
    case 'export':exportData();break;
    case 'import':document.querySelector('#import-file').click();break;
    case 'import-confirm':{const imported=modalContext?.imported;if(imported){storageBlocked=false;const old=state;state=imported;if(persist()){closeModal();go('home');toast('Данные восстановлены');}else state=old;}break;}
  }
});
document.addEventListener('input',event=>{const t=event.target;
  if(t.id==='search'){query=t.value;listLimit=60;document.querySelector('#results').innerHTML=exerciseResults(page==='library'?libraryPool():eligible(catalog,state.choices,mode,body,equipment),page==='generator');if(page==='library')bindListSwipes();}
  if(t.id==='replacement-search'&&modalContext?.pool)document.querySelector('#replacement-results').innerHTML=replacementResults(modalContext.pool,t.value);
  if(t.dataset.field&&state.active){const error=t.closest('.set-group').querySelector('.input-error');try{let value;if(t.dataset.field==='weight')value=parseWeight(t.value);else{if(!/^\d{1,3}$/.test(t.value)||Number(t.value)<1)throw new Error('Повторы: целое число от 1 до 999.');value=Number(t.value);}t.classList.remove('invalid');t.removeAttribute('aria-invalid');error.textContent='';state.active.exercises[state.active.index].sets[Number(t.dataset.set)][t.dataset.field]=value;persist();}catch(e){t.classList.add('invalid');t.setAttribute('aria-invalid','true');error.textContent=e.message;}}
});
document.addEventListener('change',event=>{const t=event.target;if(t.id==='count'){count=Number(t.value);plan=[];render();}if(modalContext?.type==='filters'&&(t.matches('[data-filter-option]')||t.matches('[data-filter-all]'))){if(t.matches('[data-filter-all]'))modalContext.values=[];else if(t.checked){if(!modalContext.values.includes(t.value))modalContext.values.push(t.value);}else modalContext.values=modalContext.values.filter(v=>v!==t.value);modal.querySelectorAll('[data-filter-option]').forEach(input=>input.checked=modalContext.values.includes(input.value));modal.querySelector('[data-filter-all]').checked=!modalContext.values.length;modal.querySelector('#filter-selection-count').textContent=modalContext.values.length?'Выбрано: '+modalContext.values.length:modalContext.kind==='body'?'Всё тело':'Любой инвентарь';}});
document.querySelector('#import-file').addEventListener('change',async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw new Error('Файл слишком большой. Максимум 10 МБ.');const imported=validateBackup(JSON.parse(await file.text()),catalog);modalContext={imported};showModal('Восстановить данные?',`<p class="dialog-copy">В копии ${imported.history.length} тренировок и ${Object.values(imported.choices).filter(v=>v==='favorite').length} избранных упражнений.<br><br>Эта копия заменит данные в текущем браузере. Перед заменой можно скачать текущую копию.</p><div class="dialog-actions">${button('Восстановить','import-confirm')}${button('Скачать текущую копию','export','secondary')}${button('Отмена','modal-close','secondary')}</div>`);}catch(e){toast(e.message||'Не удалось прочитать файл.');}});
window.addEventListener('storage',event=>{if(event.key!==STORAGE_KEY||!event.newValue)return;try{const updated=validateBackup(JSON.parse(event.newValue),catalog);if(updated.revision>=state.revision){state=updated;closeModal();if(page==='workout'&&!state.active)page='home';render();toast('Данные обновлены из другой вкладки');}}catch{/* Ignore invalid external writes without replacing valid state. */}});
async function init(){try{const response=await fetch('./exercises.json');if(!response.ok)throw new Error('catalog');catalog=await response.json();byID=new Map(catalog.map(e=>[e.id,e]));let raw;try{raw=localStorage.getItem(STORAGE_KEY);}catch{storageError('Браузер не даёт сохранять данные. Разреши хранение данных для этого сайта.');}if(raw){try{state=validateBackup(JSON.parse(raw),catalog);}catch{storageBlocked=true;storageError('Существующие данные не удалось прочитать. Они не перезаписаны. Восстанови резервную копию в профиле.');state.onboarded=true;page='profile';}}render();}catch{app.innerHTML=`<div class="loading">${brand()}<h1 style="margin:24px 0">Не удалось загрузить каталог</h1><p>Проверь интернет и обнови страницу.</p><button class="btn primary" id="retry-load" style="margin-top:20px">Попробовать снова</button></div>`;document.querySelector('#retry-load').onclick=()=>location.reload();}}
document.addEventListener('load',event=>{if(event.target.matches?.('.media-stage img')){const stage=event.target.closest('.media-stage');stage.querySelector('.media-loading').hidden=true;stage.querySelector('.media-failure').hidden=true;}},true);
document.addEventListener('error',event=>{if(event.target.matches?.('.media-stage img')){const stage=event.target.closest('.media-stage');event.target.hidden=true;stage.querySelector('.media-loading').hidden=true;stage.querySelector('.media-failure').hidden=false;}},true);
init();
